import { isValidDateObject } from '@ps-refarch-ux/mfe-utils';
/**
 * This function generates an array of arrays where each element in the array is a calendar day.
 * Each sub array represents one week.  Element 0 is always a sunday, and element 6 is always a Saturday.
 * In order to get all of the days of passed in month, some days from the previous month or next month must
 * be added as filler similar to what you would see on a calendar.  Calendar days not in the passed in month
 * will have the isFillerDate property set to true.
 * @param month 0 is January.  6 is July, 11 is December.
 * @param year 2022 means 2022.
 * @returns Array<Array<CalendarDay>>
 */
export function generateCalendarDays(month, year) {
    //1 is always the first day of the month
    const firstDayOfMonth = new Date(year, month, 1);
    //Incrementing the month and then putting in a 0 for the date gets you the last day of "month".
    //Note: This accounts for leap years too. :)
    const lastDayOfMonth = new Date(year, month + 1, 0);
    const weeks = [];
    let currentWeek = [];
    let firstDate = 1;
    if (firstDayOfMonth.getDay() > 0) {
        //Since the first day of the month isn't on Sunday, we need to decrement firstDate
        //So the loop below can create filler dates.
        firstDate -= firstDayOfMonth.getDay();
    }
    let lastDate = lastDayOfMonth.getDate();
    if (lastDayOfMonth.getDay() < 6) {
        //Since the last day of the month isn't on Saturday, we need to increment lastDate
        //So the loop below can create filler dates.
        lastDate += 7 - lastDayOfMonth.getDay();
    }
    for (let date = firstDate; date <= lastDate; date++) {
        //So this is a really cool trick.  If you put in a negative number into the date function it will create
        //a date from the previous month.  Ex: new Date(2022, 6, -4) creates June 26, 2022 even though 6 means July.
        //The same holds true for having the date larger than 31.  Ex: new Date(2022, 6, 32) creates August 1, 2022.
        //This behavior lets us roll from -4 to 37 for July of 2022 and it will create all the dates we need so long
        //as we increment by 1 each time through the loop.
        const d = new Date(year, month, date);
        //The object being pushed here is a CalendarDay object.
        currentWeek.push({
            dateObj: d,
            dateNumber: d.getDate(),
            isWeekend: d.getDay() === 0 || d.getDay() === 6,
            isFillerDate: d.getMonth() !== month
        });
        if (d.getDay() === 6) {
            weeks.push(currentWeek);
            currentWeek = [];
        }
    }
    return weeks;
}
export function isDateInDateRange(date, dateRange) {
    const dateTime = date.getTime();
    const startTime = dateRange.start.getTime();
    const endTime = dateRange.end.getTime();
    if (startTime <= dateTime && dateTime <= endTime) {
        return true;
    }
    return false;
}
export function isSameYearMonthDay(date1, date2) {
    if (date1 === undefined || date2 === undefined) {
        return false;
    }
    return (date1.getFullYear() === date2.getFullYear() &&
        date1.getMonth() === date2.getMonth() &&
        date1.getDate() === date2.getDate());
}
export function isValidDate(d) {
    return d instanceof Date && !isNaN(d);
}
export function removeTimeFromDate(d) {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}
export function getDateFromAttribute(element, attributeName) {
    const dateAsString = element.getAttribute(attributeName);
    if (dateAsString == null) {
        //If the attribute is not set then we just return undefined.
        return;
    }
    const regex = /^((0?[1-9]|1[0-2])\/(0?[1-9]|[12][0-9]|3[01])\/\d{4})$/;
    if (!regex.test(dateAsString)) {
        console.error(`${dateAsString} is not valid for the attribute ${attributeName}, which must be in mm/dd/yyyy format, for the following element`, element);
        return;
    }
    const date = new Date(dateAsString);
    if (!isValidDateObject(date)) {
        //If it isn't a valid date object then we just return undefined
        return;
    }
    return date;
}
